// reszta bez zmian

// (kod identyczny jak w Zadaniu 5, ze zmiana flagi:)
ProcessBuilder pb = new ProcessBuilder(javaExe, "-Xlog:gc", "-XX:+UseG1GC", sourceFile.toString());
// reszta bez zmian

for (String flag : List.of("-XX:+UseSerialGC", "-XX:+UseParallelGC", "-XX:+UseG1GC")) {
    String output = runAndCapture(flag);
    long gcLines = output.lines().filter(l -> l.contains("GC")).count();
    System.out.println(flag + ": " + gcLines + " linii z GC");
