// Scenariusz: nocny job ETL (Extract-Transform-Load) przetwarzajacy miliony rekordow z
// plikow CSV do hurtowni danych, uruchamiany o 2:00 w nocy, gdy ZADEN uzytkownik nie
// czeka na natychmiastowa odpowiedz systemu. W tym scenariuszu jedynym liczacym sie
// kryterium jest CALKOWITY czas trwania calego joba (np. 'musi skonczyc sie przed 6:00
// rano') - pojedyncze pauzy GC (nawet kilkusekundowe) NIE MAJA znaczenia, bo nikt ich nie
// odczuwa w czasie rzeczywistym. Parallel GC, zoptymalizowany pod throughput (mniej czasu
// CPU 'zmarnowanego' na GC wzgledem czasu pracy), skroci CALKOWITY czas przetwarzania
// bardziej niz G1, ktory swiadomie POSWIECA troche throughput na rzecz przewidywalnych,
// krotszych pauz - tu zbednych.

// Scenariusz: system transakcyjny gieldowy/platniczy z UMOWNYM SLA maksymalnego
// opoznienia odpowiedzi ponizej 10 milisekund dla KAZDEGO zadania. Parallel GC, mimo
// dobrego throughput, moze od czasu do czasu wygenerowac pauze stop-the-world rzedu
// setek milisekund lub wiecej (szczegolnie przy wiekszej stercie) - JEDNA taka pauza
// wystarczy, zeby zlamac SLA i spowodowac np. utracona transakcje lub kare umowna.
// ZGC/Shenandoah, ktorych GLOWNYM celem sa pauzy rzedu POJEDYNCZYCH milisekund
// NIEZALEZNIE od rozmiaru sterty (dzieki wykonywaniu wiekszosci pracy wspolbieznie z
// aplikacja), sa w tym scenariuszu ZDECYDOWANIE lepszym wyborem, mimo nizszego surowego
// throughput i wiekszego footprintu pamieciowego.

String source = """
    public class App {
        public static void main(String[] args) {
            int count = Integer.parseInt(args[0]);
            for (int i = 0; i < count; i++) { byte[] j = new byte[64]; }
            System.out.println("koniec, count=" + count);
        }
    }
    """;
// uruchomienie: java -Xlog:gc -XX:+UseG1GC App.java 100000
// uruchomienie: java -Xlog:gc -XX:+UseG1GC App.java 500000
// porownaj liczbe linii logu GC miedzy obiema probami - wiecej alokacji = zazwyczaj wiecej cykli GC.

for (String flag : List.of("-XX:+UseSerialGC", "-XX:+UseParallelGC", "-XX:+UseG1GC")) {
    long start = System.nanoTime();
    runProcess(flag, javaExe, "-Xlog:gc", flag, sourceFile.toString());
    long elapsedMs = (System.nanoTime() - start) / 1_000_000;
    System.out.println(flag + ": " + elapsedMs + " ms");
}

for (String flag : List.of("-XX:+UseSerialGC", "-XX:+UseParallelGC", "-XX:+UseG1GC")) {
    String output = runAndCapture(flag);
    long pauseLines = output.lines().filter(l -> l.contains("Pause")).count();
    System.out.println(flag + ": " + pauseLines + " linii z 'Pause'");
}

ProcessBuilder pb = new ProcessBuilder(javaExe, "-Xmx16m", "-Xms16m", "-Xlog:gc", "-XX:+UseG1GC", sourceFile.toString());
// oczekiwany wynik: WIECEJ linii logu GC niz przy domyslnym (wiekszym) rozmiarze sterty,
// bo maly heap zapelnia sie szybciej, wymuszajac czestsze cykle GC.

// Source-file launch (JEP 330, wprowadzony w Javie 11) pozwala uruchomic pojedynczy plik
// zrodlowy Javy BEZPOSREDNIO komenda `java Plik.java`, BEZ osobnego, jawnego kroku
// kompilacji przez javac. JVM kompiluje plik W PAMIECI (bez zapisywania .class na dysku)
// i od razu uruchamia jego metode main() - idealne dla prostych skryptow/demo, jak GcDemoApp
// w tej lekcji, gdzie tworzenie osobnego kroku kompilacji byloby zbednym narzutem.

for (int threads : new int[]{1, 4}) {
    long start = System.nanoTime();
    ProcessBuilder pb = new ProcessBuilder(javaExe, "-Xlog:gc", "-XX:+UseParallelGC", "-XX:ParallelGCThreads=" + threads, sourceFile.toString());
    pb.redirectErrorStream(true);
    Process p = pb.start();
    p.getInputStream().readAllBytes();
    p.waitFor(10, TimeUnit.SECONDS);
    long elapsedMs = (System.nanoTime() - start) / 1_000_000;
    System.out.println("ParallelGCThreads=" + threads + ": " + elapsedMs + " ms");
}

System.out.printf("%-15s | %-10s | %-10s | %s%n", "Kolektor", "Czas(ms)", "Linie GC", "Kod wyjscia");
for (String flag : List.of("-XX:+UseSerialGC", "-XX:+UseParallelGC", "-XX:+UseG1GC")) {
    long start = System.nanoTime();
    String output = runAndCapture(flag);
    long ms = (System.nanoTime() - start) / 1_000_000;
    long gcLines = output.lines().filter(l -> l.contains("GC")).count();
    System.out.printf("%-15s | %-10d | %-10d | %s%n", flag, ms, gcLines, 0);
}

// Parallel GC byl domyslny w czasach, gdy typowe aplikacje mialy mniejsze sterty i
// priorytetem byla surowa przepustowosc, a dluzsze, mniej przewidywalne pauzy byly
// akceptowalne. Wraz z rozwojem aplikacji serwerowych o coraz WIEKSZYCH stertach
// (wielogigabajtowych) i rosnacym znaczeniem responsywnosci (uzytkownicy oczekuja szybkich
// odpowiedzi, systemy interaktywne, mikroserwisy z SLA), potrzebny byl kolektor lepiej
// BALANSUJACY throughput z PRZEWIDYWALNYMI pauzami, zamiast maksymalizowac tylko jeden
// wymiar. G1, dzieki podzialowi sterty na regiony i strategii 'sprzataj najpierw tam,
// gdzie najwiecej smieci', oferuje wlasnie taki rozsadny kompromis ze SKALOWALNOSCIA do
// wiekszych sterty niz Parallel - dlatego zastapil go jako domyslny wybor od Javy 9,
// lepiej pasujac do WSPOLCZESNEGO profilu typowej aplikacji produkcyjnej.

ProcessBuilder pb = new ProcessBuilder(javaExe, "-XX:+UseSerialGC", "-XX:+UseG1GC", sourceFile.toString());
pb.redirectErrorStream(true);
Process p = pb.start();
String output = new String(p.getInputStream().readAllBytes());
p.waitFor(10, TimeUnit.SECONDS);
System.out.println("Kod wyjscia: " + p.exitValue());
System.out.println("Output: " + output);
// oczekiwany wynik: JVM odmawia startu (kod wyjscia != 0) z komunikatem o konfliktujacych
// flagach kolektora GC - nie mozna wlaczyc 2 roznych kolektorow jednoczesnie.

// Na podstawie faktycznie zaobserwowanego outputu z uruchomienia Lesson09 (wartosci moga
// sie roznic na innej maszynie/wersji JDK, ale typowe roznice to):
// 1. NAZWA kolektora w logu jest inna - G1 wypisuje linie z 'G1' w nazwie fazy (np.
//    'Pause Young (Normal) (G1 Evacuation Pause)'), podczas gdy Serial/Parallel maja
//    prostsze nazwy faz (np. 'Pause Young (Allocation Failure)').
//    2. LICZBA linii logu GC bywa RÓŻNA miedzy kolektorami dla tego samego obciazenia -
//    G1 (dzielacy sterte na regiony) czesto generuje inna czestotliwosc/granularnosc
//    cykli niz Serial/Parallel (dzialajace na ciaglych generacjach), co objawia sie
//    inna liczba linii w przechwyconym logu.

static void benchmarkCollectors(List<String> flags, Path sourceFile, String javaExe) throws Exception {
    for (String flag : flags) {
        long start = System.nanoTime();
        ProcessBuilder pb = new ProcessBuilder(javaExe, "-Xlog:gc", flag, sourceFile.toString());
        pb.redirectErrorStream(true);
        Process p = pb.start();
        String output = new String(p.getInputStream().readAllBytes());
        p.waitFor(10, TimeUnit.SECONDS);
        long ms = (System.nanoTime() - start) / 1_000_000;
        long gcLines = output.lines().filter(l -> l.contains("GC")).count();
        System.out.println(flag + ": " + ms + "ms, " + gcLines + " linii GC");
    }
}

benchmarkCollectors(List.of("-XX:+UseSerialGC", "-XX:+UseParallelGC", "-XX:+UseG1GC"), sourceFile, javaExe);

for (String heapSize : List.of("-Xmx16m", "-Xmx64m", "-Xmx256m")) {
    ProcessBuilder pb = new ProcessBuilder(javaExe, heapSize, "-Xlog:gc", "-XX:+UseG1GC", sourceFile.toString());
    pb.redirectErrorStream(true);
    Process p = pb.start();
    String output = new String(p.getInputStream().readAllBytes());
    p.waitFor(10, TimeUnit.SECONDS);
    long gcLines = output.lines().filter(l -> l.contains("GC")).count();
    System.out.println(heapSize + ": " + gcLines + " linii GC");
}
// oczekiwana zaleznosc: mniejszy -Xmx -> WIECEJ linii logu GC (heap zapelnia sie szybciej).

String variantA = "public class AppA { public static void main(String[] a) { for (int i=0;i<200_000;i++) { byte[] j = new byte[16]; } System.out.println(\"A koniec\"); } }";
String variantB = "import java.util.*; public class AppB { static List<byte[]> kept = new ArrayList<>(); public static void main(String[] a) { for (int i=0;i<5_000;i++) { kept.add(new byte[8192]); } System.out.println(\"B koniec, size=\" + kept.size()); } }";
// uruchom oba warianty z -XX:+UseG1GC -Xlog:gc i porownaj liczbe/tresc linii logu GC -
// wariant B (dluzej zyjace obiekty, osiagalne caly czas) powinien wykazywac inny wzorzec
// (mozliwe awansowanie do starej generacji) niz wariant A (czysto mloda generacja).

static int runProcessWithRetry(String description, String... command) throws IOException, InterruptedException {
    for (int attempt = 1; attempt <= 3; attempt++) {
        ProcessBuilder pb = new ProcessBuilder(command);
        pb.redirectErrorStream(true);
        Process p = pb.start();
        String output = new String(p.getInputStream().readAllBytes());
        boolean finished = p.waitFor(10, TimeUnit.SECONDS);
        if (finished) {
            System.out.println(description + " powiodl sie przy probie " + attempt);
            return p.exitValue();
        }
        p.destroyForcibly();
        System.out.println(description + ": timeout, proba " + attempt + "/3");
    }
    System.out.println(description + ": porazka po 3 probach");
    return -1;
}

Pattern pausePattern = Pattern.compile("(\\d+\\.\\d+)ms");
for (String flag : List.of("-XX:+UseSerialGC", "-XX:+UseParallelGC", "-XX:+UseG1GC")) {
    String output = runAndCapture(flag);
    double totalMs = 0;
    Matcher matcher = pausePattern.matcher(output);
    while (matcher.find()) {
        totalMs += Double.parseDouble(matcher.group(1));
    }
    System.out.println(flag + ": laczny czas pauz = " + totalMs + " ms");
}

String bigAllocSource = "public class BigApp { public static void main(String[] a) { java.util.List<byte[]> kept = new java.util.ArrayList<>(); for (int i=0;i<1_000_000;i++) { kept.add(new byte[32]); } System.out.println(\"koniec\"); } }";
// zapisz do pliku, uruchom z -Xmx8m dla kazdego kolektora, sprawdz exitValue()
// jesli wszystkie 1 000 000 obiektow jest TRZYMANYCH (osiagalnych) w liscie, a ich LACZNY
// rozmiar (~32MB) przekracza -Xmx8m, GC NIE MA jak odzyskac miejsca (nic nie jest
// nieosiagalne) - oczekiwany wynik to OutOfMemoryError: Java heap space i kod wyjscia != 0
// dla WSZYSTKICH 3 kolektorow, niezaleznie od algorytmu - GC nie moze 'wyczarowac' pamieci
// dla wciaz osiagalnych danych.

// Dla serwera servletowego z _07_servlets (embedded Tomcat obslugujacy zadania HTTP w
// czasie rzeczywistym) najlepszym domyslnym wyborem byloby G1 GC. Serwer taki obsluguje
// wielu uzytkownikow rownolegle, ktorzy oczekuja SZYBKICH odpowiedzi - dluga pauza
// stop-the-world (typowa dla Parallel GC pod obciazeniem) bezposrednio przekladalaby sie
// na 'zawieszenie' odpowiedzi dla WSZYSTKICH aktywnych zadan naraz, co uzytkownicy
// odczuliby jako czasowe 'zawieszenie sie' aplikacji. Jednoczesnie serwer nie ma
// zazwyczaj tak EKSTREMALNYCH wymagan opoznieniowych jak system transakcyjny
// (milisekundy), wiec pelny koszt footprintu ZGC/Shenandoah nie jest konieczny. G1 daje
// wlasnie taki rozsadny kompromis - przewidywalne, stosunkowo krotkie pauzy przy
// akceptowalnym throughput, dokladnie pasujace do profilu typowego serwera aplikacyjnego.

for (String flag : List.of("-XX:+UseSerialGC", "-XX:+UseParallelGC", "-XX:+UseG1GC")) {
    List<Long> times = new ArrayList<>();
    for (int run = 0; run < 3; run++) {
        long start = System.nanoTime();
        runProcess(flag, javaExe, "-Xlog:gc", flag, sourceFile.toString());
        times.add((System.nanoTime() - start) / 1_000_000);
    }
    double avg = times.stream().mapToLong(Long::longValue).average().orElse(0);
    long min = Collections.min(times), max = Collections.max(times);
    System.out.println(flag + ": srednia=" + avg + "ms, min=" + min + "ms, max=" + max + "ms");
}

// ADR: Wybor kolektora GC dla platformy e-commerce
// KONTEKST: Aplikacja e-commerce obsluguje tysiace jednoczesnych uzytkownikow przegladajacych
// katalog i skladajacych zamowienia, z wyraznymi szczytami ruchu (np. wyprzedaze, Black Friday).
// Uzytkownicy oczekuja SZYBKICH, responsywnych stron - dluga pauza GC bezposrednio przeklada
// sie na 'zawieszone' zamowienie i potencjalna utrate sprzedazy. Jednoczesnie aplikacja musi
// obslugiwac DUZY wolumen requestow rownolegle, wiec calkowity throughput tez ma znaczenie.
// DECYZJA: Wybieramy G1 GC jako domyslny kolektor, z mozliwoscia przejscia na ZGC, jesli
// pomiary produkcyjne wykaza, ze pauzy G1 wciaz przekraczaja akceptowalny prog podczas
// najwiekszych szczytow ruchu. KONSEKWENCJE: G1 daje przewidywalne, stosunkowo krotkie pauzy
// (konfigurowalne przez -XX:MaxGCPauseMillis), co minimalizuje ryzyko zauwazalnych
// 'zawieszen' dla klientow, kosztem nieco nizszego surowego throughput niz Parallel GC -
// akceptujemy ten kompromis, bo UX podczas szczytu jest priorytetem biznesowym wyzszym niz
// maksymalny throughput. Bedziemy monitorowac metryki pauz GC na produkcji (patrz Lesson08) i
// rewidowac decyzje, jesli dane wykaza potrzebe przejscia na kolektor low-latency.

record CollectorResult(String flag, long timeMs, long gcLines) { }

List<CollectorResult> results = new ArrayList<>();
for (String flag : List.of("-XX:+UseSerialGC", "-XX:+UseParallelGC", "-XX:+UseG1GC")) {
    long start = System.nanoTime();
    String output = runAndCapture(flag);
    long ms = (System.nanoTime() - start) / 1_000_000;
    long gcLines = output.lines().filter(l -> l.contains("GC")).count();
    results.add(new CollectorResult(flag, ms, gcLines));
}

System.out.println("=== RAPORT KONCOWY: PORONANIE KOLEKTOROW GC ===");
System.out.printf("%-25s | %-10s | %-10s%n", "Kolektor", "Czas(ms)", "Linie GC");
for (CollectorResult r : results) {
    System.out.printf("%-25s | %-10d | %-10d%n", r.flag(), r.timeMs(), r.gcLines());
}

CollectorResult fastest = results.stream().min(Comparator.comparingLong(CollectorResult::timeMs)).orElseThrow();
System.out.println("\nRekomendacja (na podstawie tego konkretnego, bounded testu): " + fastest.flag() + " byl najszybszy.");
